{"summary":"Count occurrences of key identifying strings in each PDF", "security_risk":"LOW", "command":"python3 - <<'PY'
import fitz, re

def ref_page(doc):
    for i,p in enumerate(doc):
        if re.search(r'\breferences\b', p.get_text().lower()):
            return i
    return None

papers = {
  1: {
    'names':["Yueqian Lin","Zhengmian Hu","Qinsi Wang","Yudong Liu","Hengfan Zhang","Jayakumar Subramanian","Nikos Vlassis","Hai “Helen” Li","Hai Helen Li","Yiran Chen"],
    'affils':["Duke University, Durham, NC, USA","Adobe, San Jose, CA, USA"],
    'others':["yueqian.lin@duke.edu","zhengmianh@adobe.com","arXiv:2509.26542v1","arXiv:2509.26542"],
  },
  2: {
    'names':["Jiatong Shi","Yueqian Lin","Xinyi Bai","Keyi Zhang","Yuning Wu","Yuxun Tang","Yifeng Yu","Qin Jin","Shinji Watanabe"],
    'affils':["Carnegie Mellon University","Duke Kunshan University","Cornell University","Multimodal Art Projection Community","Renmin University of China","Georgia Institute of Technology"],
    'others':["jiatongs@cs.cmu.edu","10.21437/Interspeech.2024-33","Interspeech"],
  },
  3: {
    'names':["Yueqian Lin","Yuzhe Fu","Jingyang Zhang","Yudong Liu","Jianyi Zhang","Jingwei Sun","Hai Li","Yiran Chen"],
    'affils':[],
    'others':["yl768@duke.edu","Proceedings of the International Conference on Machine Learning 2025","International Conference on Machine Learning 2025","ICML 2025"],
  }
}

for i, cfg in papers.items():
    path = f'/root/paper{i}.pdf'
    doc = fitz.open(path)
    r = ref_page(doc)
    stop = r if r is not None else doc.page_count
    print('\n'+'='*80)
    print(path, 'pages', doc.page_count, 'references at', r)
    for group in ['names','affils','others']:
        for s in cfg[group]:
            c=0
            for pn in range(stop):
                c += len(doc[pn].search_for(s))
            if c:
                print(f'  {group}: {s!r} -> {c} matches')
            else:
                print(f'  {group}: {s!r} -> 0')
    doc.close()
PY"}

