{"summary":"Scan all papers for funding, correspondence, and URL leakage", "security_risk":"LOW", "command":"python3 - <<'PY'
import fitz, re

def ref_page(doc):
    for i,p in enumerate(doc):
        if re.search(r'\breferences\b', p.get_text().lower()):
            return i
    return None

keywords = [r'correspond', r'nsf', r'aro', r'grant', r'supported', r'github\.com', r'https?://', r'openreview', r'arxiv']
kw_re = re.compile('|'.join(keywords), re.I)

for n in (1,2,3):
    path=f'/root/paper{n}.pdf'
    doc=fitz.open(path)
    r=ref_page(doc)
    stop=r if r is not None else doc.page_count
    print('\n'+'='*80)
    print(path,'stop at',stop)
    for i in range(stop):
        t=doc[i].get_text('text')
        hits=[]
        for ln in t.splitlines():
            if kw_re.search(ln):
                hits.append(ln.strip())
        if hits:
            print('page',i)
            for h in hits[:25]:
                print(' ',h)
    doc.close()
PY"}

