{"summary":"Extract URLs and grant-like identifiers from papers pre-references", "security_risk":"LOW", "command":"python3 - <<'PY'
import fitz, re

def ref_page(doc):
    for i,p in enumerate(doc):
        if re.search(r'\breferences\b', p.get_text().lower()):
            return i
    return None

url_re = re.compile(r'https?://\S+', re.I)
# grant-like: NSF 1234567, NSF grants #123, #123..., ARO W911..., alphanumeric program codes
grant_re = re.compile(r'(?:NSF\s*grants?\s*)?(?:#\d{5,8}|NSF\s*\d{6,8}|W911NF-[0-9-]+\d|IRI\w+\d+|ARO\s*W911NF-[0-9-]+\d)', re.I)

for n in (1,2,3):
    path=f'/root/paper{n}.pdf'
    doc=fitz.open(path)
    r=ref_page(doc)
    stop=r if r is not None else doc.page_count
    urls=set(); grants=set();
    for i in range(stop):
        t=doc[i].get_text('text')
        for u in url_re.findall(t):
            u=u.rstrip(').,;]')
            urls.add(u)
        for g in grant_re.findall(t):
            grants.add(g.strip())
    print('\n'+'='*80)
    print(path)
    print('URLs:')
    for u in sorted(urls):
        print(' ',u)
    print('Grant-like tokens:')
    for g in sorted(grants):
        print(' ',g)
    doc.close()
PY"}

