    urls=set(); grants=set();
    for i in range(stop):
        t=doc[i].get_text('text')
        for u in url_re.findall(t):
            u=u.rstrip(').,;]')
            urls.add(u)
        for g in grant_re.findall(t):
            grants.add(g.strip())
    print('\n'+'='*80)
    print(path)
    print('URLs:')
    for u in sorted(urls):
